import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { delegateCombine, delegateRemove } from 'igniteui-core/type';
import { IgcTemplateCellUpdatingEventArgs } from "./igc-template-cell-updating-event-args";
import { IgcDataGridColumnComponent } from "./igc-data-grid-column-component";
import { IgcDefinitionBaseComponent } from "./igc-definition-base-component";
import { TemplateColumn } from "./TemplateColumn";
import { getAllPropertyNames, fromSpinal, toSpinal, initializePropertiesFromCss, NamePatcher } from "igniteui-core/componentUtil";
import { IgEvent } from "igniteui-core/IgEvent";
import { IgcCellStyleRequestedEventArgs } from "./igc-cell-style-requested-event-args";
import { IgcTemplateContentComponent } from "igniteui-core/igc-template-content-component";
import { IgcCellInfo } from './igc-cell-info';
import { html, TemplateFunction } from 'igniteui-core/template';
import { RegisterElementHelper } from 'igniteui-core/module-manager';


/**
 * A column with customizable content.
*/
export class IgcTemplateColumnComponent extends IgcDataGridColumnComponent
{
    protected createImplementation(): TemplateColumn {
        return new TemplateColumn();
    }
    public get i(): TemplateColumn {
        return this._implementation;
    }
    constructor() {
        super();

        this.cellInfoChanged = this.cellInfoChanged.bind(this);
    }

    private beforeStyleKeyRequested(s: IgcTemplateColumnComponent, e: IgcCellStyleRequestedEventArgs) {
        if (this.template == null && this.templateSelector == null) {
            return;
        }
        if (!this._hasSelector) {
            return;
        }

        var selector = this._templateSelector;
        if (selector == null) {
            return;
        }

        var actualTemplate = this._templateSelector(this, e.resolvedValue);
        if (actualTemplate == null) {
            return;
        }

        let key: string;
        if (this._selectorStyles.has(actualTemplate)) {
            key = this._selectorStyles.get(actualTemplate);
            e.styleKey = key;
        }
        else {
            if (this._selectorStyles.size < 1000) {
                key = "template_" + this.field + "_" + this._keyCount;
                this._selectorStyles.set(actualTemplate, key);
                this._selectorTemplates[key] = actualTemplate;
                this._keyCount++;
                e.styleKey = key;
            }
        }
    }

    private _templateCells: Element[] = [];
    private _activeCellContent: Map<Element, IgcTemplateContentComponent> = new Map<Element, IgcTemplateContentComponent>();
    private _activeCellContentElements: Map<Element, any> = new Map<Element, any>();
    private _templateCellInitialData: Map<Element, any> = new Map<Element, any>();
    private _templateCellInitialTemplate: Map<Element, any> = new Map<Element, any>();

    private beforeCellUpdating(s: IgcTemplateColumnComponent, e: IgcTemplateCellUpdatingEventArgs) {
        if (this.template == null && this.templateSelector == null) {
            return;
        }
        let info = e.cellInfo;
        let existingView: IgcTemplateContentComponent;

        if (!info.isContentDirty &&
            !info.isDataDirty &&
            !info.isSizeDirty) {
            return;
        }

        var actualTemplate = this._template;
        if (this._hasSelector) {
            if (this._selectorTemplates.has(info.styleKey)) {
                actualTemplate = this._selectorTemplates.get(info.styleKey);
            }
        }

        var internalContent = e.content;
        if (internalContent == null) {
            return;
        }
        if (this._activeCellContent.has(internalContent)) {
            var templateView = this._activeCellContent.get(internalContent);
            templateView.context = info;
            this.updateCellInfo(info);

            if (templateView.template != actualTemplate) {
                (templateView as any).template = actualTemplate;
            }
            else {
                existingView = templateView;
            }
        }
        else {
            this._templateCells.push(internalContent);
            this._templateCellInitialData.set(internalContent, info);
            this.updateCellInfo(info);
            this._templateCellInitialTemplate.set(internalContent, actualTemplate);
            this.updateTemplates();
        }
    }

    private _currCellInfo: IgcCellInfo = null;
    private updateCellInfo(info: IgcCellInfo) {
        let oldInfo = this._currCellInfo;
        if (oldInfo != null) {
            oldInfo.removeOnChangedListener(this.cellInfoChanged);
        }

        this._currCellInfo = info;
        if (this._currCellInfo != null) {
            this._currCellInfo.addOnChangedListener(this.cellInfoChanged);
        }
    }

    private cellInfoChanged() {
        this.updateTemplates();
    }

    private dummyStyleKeyRequested(s: IgcTemplateColumnComponent, e: IgcCellStyleRequestedEventArgs) {

    }

    private dummyCellUpdating(s: IgcTemplateColumnComponent, e: IgcTemplateCellUpdatingEventArgs) {

    }

    private get hasTemplate(): boolean {
        return this._template != null || this._templateSelector != null;
    }

    private _template: TemplateFunction = null;
    public get template(): TemplateFunction {
        return this._template;
    }
    public set template(value: TemplateFunction) {
        let oldValue = this.hasTemplate;
        this._template = value;
        this.ensureTemplateEvents(oldValue);
        this.onTemplateChanged();
    }

    private _templateSelector: (column: IgcTemplateColumnComponent, value: any) => TemplateFunction = null;
    public get templateSelector(): (column: IgcTemplateColumnComponent, value: any) => TemplateFunction {
        return this._templateSelector;
    }
    public set templateSelector(value: (column: IgcTemplateColumnComponent, value: any) => TemplateFunction) {
        let oldValue = this.hasTemplate;
        this._templateSelector = value;
        this._hasSelector = this._templateSelector != null;
        this.ensureTemplateEvents(oldValue);
        this.onTemplateChanged();
    }
    private _hasSelector: boolean = false;

    private onTemplateChanged() {
        this._selectorStyles.clear();
        this._selectorTemplates.clear();
        this._keyCount = 0;
    }


    private _selectorStyles: Map<TemplateFunction, string> = new Map<TemplateFunction, string>()
    private _selectorTemplates: Map<string, TemplateFunction> = new Map<string, TemplateFunction>()
    private _keyCount: number = 0;

    private updateTemplates() {
        let templates = [];
        if (this._templateCells && this._templateCells.length > 0) {
            for (let i = 0; i < this._templateCells.length; i++) {
                let t = this._templateCells[i];
                if (this._activeCellContentElements.has(t)) {
                    templates.push(this._activeCellContentElements.get(t));
                } else {
                    let templ = document.createElement("igc-template-content") as IgcTemplateContentComponent;
                    templ.owner = this._templateCells[i];
                    this._activeCellContentElements.set(t, templ);
                    this._activeCellContent.set(t, templ);
                    templates.push(templ);
                    t.appendChild(templ);

                    if (this._templateCellInitialTemplate.has(templ.owner)) {
                        templ.template = this._templateCellInitialTemplate.get(templ.owner);
                        this._templateCellInitialTemplate.delete(templ.owner);
                    }
                    if (this._templateCellInitialData.has(templ.owner)) {
                        templ.context = this._templateCellInitialData.get(templ.owner);
                        this._templateCellInitialTemplate.delete(templ.owner);
                    }
                }
            }
        }
    }

    private ensureTemplateEvents(oldValue: boolean) {
        if (this.hasTemplate && !oldValue) {
            if (!this.cellStyleKeyRequested) {
                this.cellStyleKeyRequested = this.dummyStyleKeyRequested;
                (this as any)._styleKeyRequested = null;
            }
            if (!this.cellUpdating) {
                this.cellUpdating = this.dummyCellUpdating;
                (this as any)._cellUpdating = null;
            }
        }
        if (!this.hasTemplate && oldValue) {
            if (!this.cellStyleKeyRequested) {
                this.cellStyleKeyRequested = null;
            }
            if (!this.cellUpdating) {
                this.cellUpdating = null;
            }
        }
    }

    

    	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if ((this as any).updateContentChildren) {
	            (this as any).updateContentChildren();
	        } else if ((this as any)._updateAdapters) {
	            (this as any)._updateAdapters();
	        }
	
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }

    	
	                private static _observedAttributesIgcTemplateColumnComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcTemplateColumnComponent._observedAttributesIgcTemplateColumnComponent == null) {
	                        let names = getAllPropertyNames(IgcTemplateColumnComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcTemplateColumnComponent._observedAttributesIgcTemplateColumnComponent = names;
	                    }
	                    return IgcTemplateColumnComponent._observedAttributesIgcTemplateColumnComponent;               
	                }                 
	            

    	
	                public static htmlTagName: string = "igc-template-column";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcTemplateColumnComponent._isElementRegistered) {
	                        IgcTemplateColumnComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcTemplateColumnComponent.htmlTagName,
	                            IgcTemplateColumnComponent);
	                    }
	            }

    

    

    

	

    	
	    private _cellUpdating: (s: IgcTemplateColumnComponent, e: IgcTemplateCellUpdatingEventArgs) => void = null;
	    private _cellUpdating_wrapped: any = null;
	/**
	 * Called when the cell content is being created or updated.
	*/
	
	public get cellUpdating(): (s: IgcTemplateColumnComponent, e: IgcTemplateCellUpdatingEventArgs) => void {
	return this._cellUpdating;
	}
	    public set cellUpdating(ev: (s: IgcTemplateColumnComponent, e: IgcTemplateCellUpdatingEventArgs) => void) {
	        if (this._cellUpdating_wrapped !== null) {
	            this.i.cellUpdating = delegateRemove(this.i.cellUpdating, this._cellUpdating_wrapped);
	            this._cellUpdating_wrapped = null;
	            this._cellUpdating = null;
	        }
	
	        this._cellUpdating = ev;
	        this._cellUpdating_wrapped = (o, e) => {
	            
	                    let outerArgs = new IgcTemplateCellUpdatingEventArgs();
	(<any>outerArgs)._provideImplementation(e);
	                    if ((this as any).beforeCellUpdating) {
	                        (this as any).beforeCellUpdating(this, outerArgs);
	                    }
	                    if (this._cellUpdating) {
	    this._cellUpdating(this, outerArgs);
	                    }
	
	        };
	        this.i.cellUpdating = delegateCombine(this.i.cellUpdating, this._cellUpdating_wrapped);;
	    }

    //@@ZoneRunner
}


