import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { CellKey as CellKey_internal } from "./CellKey";
import { IgcPrimaryKeyValue } from './igc-primary-key-value';
import { IgcDataGridColumnComponent } from './igc-data-grid-column-component';

/**
 * An indentifier for a specific cell in the grid.
*/
export class IgcCellKey {
    protected _implementation: any;
    private _primaryKey: IgcPrimaryKeyValue;

    public get i(): CellKey_internal {
        return this._implementation;
    }
    private onImplementationCreated() {

    }
    constructor() {
        this._implementation = new CellKey_internal();
        this._implementation.externalObject = this;
    }
    protected _provideImplementation(i: any) {
        this._implementation = i;
        (<any>this._implementation).externalObject = this;
        this.onImplementationCreated();
    }

    /**
	 * Gets or sets the primary key of the row associated with the cell.
	*/
    get primaryKey(): IgcPrimaryKeyValue {
        if (this.i.primaryKey == null) {
            return null;
        }
        if (!this._primaryKey) {
            this._primaryKey = new IgcPrimaryKeyValue(this.i.primaryKey.key, this.i.primaryKey.value);
        }

        return this._primaryKey;
    }
    set primaryKey(v: IgcPrimaryKeyValue) {
        this.i.primaryKey = v.i;
    }

    	/**
	 * Gets or sets the row data object associated with the cell.
	*/
	get rowItem() : any {
		return this.i.h as any;
	}
	set rowItem(v: any) {
	                                        this.i.h = v;
	}
	/**
	 * Gets or sets the column name associated with the cell.
	 * All columns in the grid must have a unique name. That unique name is what is used for this property.
	*/
	get columnUniqueKey() : string {
		return (this.i.j as string);
	}
	set columnUniqueKey(v: string) {
		this.i.j = v;
	}
	/**
	 * Gets or sets the resolved column object associated with this cell.
	*/
	get resolvedColumn() : IgcDataGridColumnComponent {
	                                        const r = this.i.b;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcDataGridColumnComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}

    	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	if (this.primaryKey && (this.primaryKey as any).name && (this.primaryKey as any).name == name) { return this.primaryKey; }
	
	        return null;
	    }

    

    
}
