/**
 * Event arguments for the CellValueChanging event
*/
export class IgcGridCellValueChangingEventArgs {

    protected createImplementation(): GridCellValueChangingEventArgs_internal {
        return new GridCellValueChangingEventArgs_internal();
    }
    protected _implementation: any;
    public get i(): GridCellValueChangingEventArgs_internal {
        return this._implementation;
    }
    private onImplementationCreated() {

    }
    constructor() {
        this._implementation = this.createImplementation();
        (<any>this._implementation).externalObject = this;
        this.onImplementationCreated();
    }
    protected _provideImplementation(i: any) {
        this._implementation = i;
        (<any>this._implementation).externalObject = this;
        this.onImplementationCreated();
    }

    /**
	 * The backing information for the current cell.
	*/
    get cellInfo(): IgcCellInfo {
        if (this.i.cellInfo == null) {
            return null;
        }

        if (!(<any>this.i.cellInfo).externalObject) {
            let ext: any = null;
            switch ((<any>this.i.cellInfo).$type.name) {
                case "DateTimeCellModel":
                    ext = new IgcDateTimeCellInfo();
                    break;
                case "ImageCellModel":
                    ext = new IgcImageCellInfo();
                    break;
                case "NumericCellModel":
                    ext = new IgcNumericCellInfo();
                    break;
                case "RowSeparatorModel":
                    ext = new IgcRowSeparatorInfo();
                    break;
                case "SectionHeaderCellModel":
                    ext = new IgcSectionHeaderCellInfo();
                    break;
                case "TemplateCellModel":
                    ext = new IgcTemplateCellInfo();
                    break;
                case "TemplateHeaderCellModel":
                    ext = new IgcTemplateHeaderCellInfo();
                    break;
                case "TemplateSectionHeaderCellModel":
                    ext = new IgcTemplateSectionHeaderCellInfo();
                    break;
                case "TextCellModel":
                    ext = new IgcTextCellInfo();
                    break;
                case "TextHeaderCellModel":
                    ext = new IgcTextHeaderCellInfo();
                    break;
            }
            (<any>ext)._implementation = this.i.cellInfo;
            (<any>this.i.cellInfo).externalObject = ext;
        }

        return (<any>this.i.cellInfo).externalObject;
    }

    	/**
	 * Gets the edit ID for this value change.
	*/
	get editID() : number {
		return (this.i.c as number);
	}
	set editID(v: number) {
		this.i.c = +v;
	}
	/**
	 * Gets the column the cell belongs to.
	*/
	get column() : IgcDataGridColumnComponent {
	                                        const r = this.i.b;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcDataGridColumnComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set column(v: IgcDataGridColumnComponent) {
		v == null ? this.i.b = null : this.i.b = v.i;
	}
	/**
	 * Gets the row item associated with the change.
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * Gets the old cell value.
	*/
	get oldValue() : any {
		return this.i.f as any;
	}
	set oldValue(v: any) {
	                                        this.i.f = v;
	}
	/**
	 * Gets the new cell value.
	*/
	get newValue() : any {
		return this.i.e as any;
	}
	set newValue(v: any) {
	                                        this.i.e = v;
	}

    

    

    
}
