import { Enum, ValueType, markEnum, Type } from "igniteui-core/type";

/**
 * Indicates which type of filter UI to use.
 */
export enum FilterUIType {
	/**
	 * Filtering is displayed within the column options menu.
	 */
	ColumnOptions = 0,
	/**
	 * A filter row is displayed. Each filter cell in the row will let you select filter operator as well as filter
	 * condition for the associated field.
	 */
	FilterRow = 1,
	/**
	 * No filter UI is used.
	 */
	None = 2
}

/**
 * @hidden 
 */
export let FilterUIType_$type = markEnum('FilterUIType', 'ColumnOptions,0|FilterRow,1|None,2');


