import { CellModelExport } from "./CellModelExport";
import { DataSourceSchemaPropertyType, DataSourceSchemaPropertyType_$type } from "igniteui-core/DataSourceSchemaPropertyType";
import { StringBuilder } from "igniteui-core/StringBuilder";
import { Base, enumGetBox, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class EditorCellModelExport extends CellModelExport {
	static $t: Type = markType(EditorCellModelExport, 'EditorCellModelExport', (<any>CellModelExport).$);
	af: boolean = false;
	ag: string = null;
	ae: DataSourceSchemaPropertyType = <DataSourceSchemaPropertyType>0;
	ah: string = null;
	protected get_ac(): string {
		return "EditorCell";
	}
	protected ad(a: StringBuilder): void {
		super.ad(a);
		a.l("isHidden: " + this.af.toString().toLowerCase() + ", ");
		a.l("editValue: '" + this.ag + "', ");
		a.l("dataType: '" + enumGetBox<DataSourceSchemaPropertyType>(DataSourceSchemaPropertyType_$type, this.ae) + "', ");
		a.l("errorMessage: '" + this.ah + "', ");
	}
}


