import { IgcEditorDefinitionComponent } from './igc-editor-definition-component';
import { EditorDefinition } from './EditorDefinition';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcEditorDefinitionModule {
    public static register(): void {
        IgcEditorDefinitionComponent.register();
        TypeRegistrar.registerCons("IgcEditorDefinitionComponent", IgcEditorDefinitionComponent);
        TypeRegistrar.register("EditorDefinition", (<any>EditorDefinition).$type);
    }
}
