import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcDefinitionBaseComponent } from "./igc-definition-base-component";
import { EditorDefinition } from "./EditorDefinition";
import { getAllPropertyNames, fromSpinal, toSpinal } from "igniteui-core/componentUtil";
import { RegisterElementHelper } from "igniteui-core/module-manager";

/**
 * Represents a base class used to configure the appearance of the column header cells.
*/
export class IgcEditorDefinitionComponent extends IgcDefinitionBaseComponent
{

protected createImplementation() : EditorDefinition
{
	return new EditorDefinition();
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : EditorDefinition {
		return this._implementation;
	}
	constructor() {
		super()
	                                     
	}
	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if ((this as any).updateContentChildren) {
	            (this as any).updateContentChildren();
	        } else if ((this as any)._updateAdapters) {
	            (this as any)._updateAdapters();
	        }
	
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }
	
	                private static _observedAttributesIgcEditorDefinitionComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcEditorDefinitionComponent._observedAttributesIgcEditorDefinitionComponent == null) {
	                        let names = getAllPropertyNames(IgcEditorDefinitionComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcEditorDefinitionComponent._observedAttributesIgcEditorDefinitionComponent = names;
	                    }
	                    return IgcEditorDefinitionComponent._observedAttributesIgcEditorDefinitionComponent;               
	                }                 
	            
	
	                public static htmlTagName: string = "igc-editor-definition";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcEditorDefinitionComponent._isElementRegistered) {
	                        IgcEditorDefinitionComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcEditorDefinitionComponent.htmlTagName,
	                            IgcEditorDefinitionComponent);
	                    }
	            }
}
