import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { FormatCellEventArgs as FormatCellEventArgs_internal } from "./FormatCellEventArgs";
import { ensureBool } from "igniteui-core/componentUtil";

export class IgcFormatCellEventArgs
{

protected createImplementation() : FormatCellEventArgs_internal
{
	return new FormatCellEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : FormatCellEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets the row index of the cell to format.
	*/
	get row() : number {
		return (this.i.c as number);
	}
	set row(v: number) {
		this.i.c = +v;
	}
	/**
	 * Gets the data item associated with the cell.
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * Gets the value that is to be displayed in the cell.
	*/
	get value() : any {
		return this.i.e as any;
	}
	set value(v: any) {
	                                        this.i.e = v;
	}
	/**
	 * Sets the formatted text to display in the cell.
	*/
	get text() : string {
		return (this.i.f as string);
	}
	set text(v: string) {
		this.i.f = v;
	}
	/**
	 * The cell is part of a summary row.
	*/
	get isSummary() : boolean {
		return (this.i.b as boolean);
	}
	set isSummary(v: boolean) {
		this.i.b = ensureBool(v);
	}
	/**
	 * The cell is part of a grouping row.
	*/
	get isGroup() : boolean {
		return (this.i.a as boolean);
	}
	set isGroup(v: boolean) {
		this.i.a = ensureBool(v);
	}
}
