import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcColumnSummaryDescriptionCollection } from "./igc-column-summary-description-collection";
import { GridSummaryDescriptionsChangedEventArgs as GridSummaryDescriptionsChangedEventArgs_internal } from "./GridSummaryDescriptionsChangedEventArgs";

/**
 * Information about the current summaries applied to the grid.
*/
export class IgcGridSummaryDescriptionsChangedEventArgs
{

protected createImplementation() : GridSummaryDescriptionsChangedEventArgs_internal
{
	return new GridSummaryDescriptionsChangedEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : GridSummaryDescriptionsChangedEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	get summaryDescriptions() : IgcColumnSummaryDescriptionCollection {
	                                        const r = this.i.summaryDescriptions;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcColumnSummaryDescriptionCollection();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set summaryDescriptions(v: IgcColumnSummaryDescriptionCollection) {
		v == null ? this.i.summaryDescriptions = null : this.i.summaryDescriptions = v.i;
	}
}
