/**
 * Represents an element in the current grouping applied to a data source or provider. Changes to this object are not observed or expected after it is initially assigned to a collection.
*/
export class IgcColumnGroupDescription extends IgcColumnSortDescription
{

protected createImplementation() : ColumnGroupDescription_internal
{
	return new ColumnGroupDescription_internal(0);
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : ColumnGroupDescription_internal {
		return this._implementation;
	}
	constructor() {
		super();
	}
	/**
	 * Gets or sets the format string for the group value.
	*/
	get valueFormat() : string {
		return (this.i.x as string);
	}
	set valueFormat(v: string) {
		this.i.x = v;
	}
	/**
	 * Gets or sets the format specifiers to use with the ValueFormat string.
	*/
	get valueFormatSpecifiers() : any[] {
		return this.i.j as any[];
	}
	set valueFormatSpecifiers(v: any[]) {
	                                            if (v && !Array.isArray(v) && typeof(v) == "string") {
	                                                const re = /\s*(?:,|\s|$)\s*/gm;
	                                                v = (v as string).split(re) as any as any[];
	                                            }
		    this.i.j = v;
	    }
	/**
	 * Gets or sets the display format for the group text in the group header.
	*/
	get displayFormat() : string {
		return (this.i.u as string);
	}
	set displayFormat(v: string) {
		this.i.u = v;
	}
	/**
	 * Gets or sets the format specifiers to use with the DisplayFormat string.
	*/
	get displayFormatSpecifiers() : any[] {
		return this.i.i as any[];
	}
	set displayFormatSpecifiers(v: any[]) {
	                                            if (v && !Array.isArray(v) && typeof(v) == "string") {
	                                                const re = /\s*(?:,|\s|$)\s*/gm;
	                                                v = (v as string).split(re) as any as any[];
	                                            }
		    this.i.i = v;
	    }
	/**
	 * Gets or sets an INTL.DateTimeFormat or INTL.NumericFormat to use to format the value.
	*/
	get formatOverride() : any {
		return this.i.q as any;
	}
	set formatOverride(v: any) {
	                                        this.i.q = v;
	}
	/**
	 * Gets or sets the display text for the group name.
	*/
	get displayName() : string {
		return (this.i.v as string);
	}
	set displayName(v: string) {
		this.i.v = v;
	}
	
	    public findByName(name: string): any {
	        
	    var baseResult = super.findByName(name);
	    if (baseResult)
	    {
	        return baseResult;
	    }
	
	if (this.valueFormatSpecifiers != null && arrayFindByName(this.valueFormatSpecifiers, name)) { return arrayFindByName(this.valueFormatSpecifiers, name); }
	if (this.displayFormatSpecifiers != null && arrayFindByName(this.displayFormatSpecifiers, name)) { return arrayFindByName(this.displayFormatSpecifiers, name); }
	
	        return null;
	    }
	
	    private _formatText: (s: IgcColumnGroupDescription, e: IgcFormatGroupTextEventArgs) => void = null;
	    private _formatText_wrapped: any = null;
	/**
	 * Called when the value is being formatted.
	*/
	
	public get formatText(): (s: IgcColumnGroupDescription, e: IgcFormatGroupTextEventArgs) => void {
	return this._formatText;
	}
	    public set formatText(ev: (s: IgcColumnGroupDescription, e: IgcFormatGroupTextEventArgs) => void) {
	        if (this._formatText_wrapped !== null) {
	            this.i.formatText = delegateRemove(this.i.formatText, this._formatText_wrapped);
	            this._formatText_wrapped = null;
	            this._formatText = null;
	        }
	
	        this._formatText = ev;
	        this._formatText_wrapped = (o, e) => {
	            
	                    let outerArgs = new IgcFormatGroupTextEventArgs();
	(<any>outerArgs)._provideImplementation(e);
	                    if ((this as any).beforeFormatText) {
	                        (this as any).beforeFormatText(this, outerArgs);
	                    }
	                    if (this._formatText) {
	    this._formatText(this, outerArgs);
	                    }
	
	        };
	        this.i.formatText = delegateCombine(this.i.formatText, this._formatText_wrapped);;
	    }
}
