import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { delegateCombine, delegateRemove } from 'igniteui-core/type';
import { EditorType, EditorType_$type } from "./EditorType";
import { IgcGridCustomFilterRequestedEventArgs } from "./igc-grid-custom-filter-requested-event-args";
import { FilterOperand as FilterOperand_internal } from "./FilterOperand";
import { FilterFactory } from "igniteui-core/FilterFactory";
import { ensureBool, ensureEnum } from "igniteui-core/componentUtil";

/**
 * A filter operand.
*/
export class IgcFilterOperand
{

protected createImplementation() : FilterOperand_internal
{
	return new FilterOperand_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : FilterOperand_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets the FilterFactory to assists in building filters.
	*/
	get filterFactory() : FilterFactory {
		return this.i.a as FilterFactory;
	}
	/**
	 * Gets or sets the ID of the filter. Must be unique from other filters in the column.
	*/
	get iD() : string {
		return (this.i.g as string);
	}
	set iD(v: string) {
		this.i.g = v;
	}
	/**
	 * Gets or sets the name for display of this custom filter.
	*/
	get displayName() : string {
		return (this.i.e as string);
	}
	set displayName(v: string) {
		this.i.e = v;
	}
	/**
	 * Gets or sets the SVG path to use for the operand icon in the filter cell.
	*/
	get icon() : string {
		return (this.i.f as string);
	}
	set icon(v: string) {
		this.i.f = v;
	}
	/**
	 * Gets or sets whether this filter requires input.
	*/
	get isInputRequired() : boolean {
		return (this.i.d as boolean);
	}
	set isInputRequired(v: boolean) {
		this.i.d = ensureBool(v);
	}
	/**
	 * The type of editor to use in the filter cell. Combo is not currently supported.
	*/
	get editorType() : EditorType {
		return this.i.b;
	}
	set editorType(v: EditorType) {
		this.i.b = ensureEnum<EditorType>(EditorType_$type, v);
	}
	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	
	        return null;
	    }
	
	    private _filterRequested: (s: IgcFilterOperand, e: IgcGridCustomFilterRequestedEventArgs) => void = null;
	    private _filterRequested_wrapped: any = null;
	/**
	 * Gets or sets a function that returns a filter expression to use.
	*/
	
	public get filterRequested(): (s: IgcFilterOperand, e: IgcGridCustomFilterRequestedEventArgs) => void {
	return this._filterRequested;
	}
	    public set filterRequested(ev: (s: IgcFilterOperand, e: IgcGridCustomFilterRequestedEventArgs) => void) {
	        if (this._filterRequested_wrapped !== null) {
	            this.i.filterRequested = delegateRemove(this.i.filterRequested, this._filterRequested_wrapped);
	            this._filterRequested_wrapped = null;
	            this._filterRequested = null;
	        }
	
	        this._filterRequested = ev;
	        this._filterRequested_wrapped = (o, e) => {
	            
	                    let outerArgs = new IgcGridCustomFilterRequestedEventArgs();
	(<any>outerArgs)._provideImplementation(e);
	                    if ((this as any).beforeFilterRequested) {
	                        (this as any).beforeFilterRequested(this, outerArgs);
	                    }
	                    if (this._filterRequested) {
	    this._filterRequested(this, outerArgs);
	                    }
	
	        };
	        this.i.filterRequested = delegateCombine(this.i.filterRequested, this._filterRequested_wrapped);;
	    }
}
