import { Enum, ValueType, markEnum, Type } from "igniteui-core/type";

/**
 * Indicates how filters will treat case sensitivity.
 */
export enum FilterComparisonType {
	/**
	 * The default case sensitivity. Default is CaseInsensitive.
	 */
	Default = 0,
	/**
	 * Filtering is performed without case sensitivity.
	 */
	CaseInsensitive = 1,
	/**
	 * Filtering is performed with case sensitivity.
	 */
	CaseSensitive = 2
}

/**
 * @hidden 
 */
export let FilterComparisonType_$type = markEnum('FilterComparisonType', 'Default,0|CaseInsensitive,1|CaseSensitive,2');


